{
  "hechos": [
    {
      "id": "H1",
      "texto": "En Puerto Celeste no se podrá circular entre las diez de la noche y las cinco de la mañana.",
      "paginas": ["P1", "P2", "P3", "P4", "P5", "P6", "P7"]
    },
    {
      "id": "H2",
      "texto": "La medida responde al incremento de robos en viviendas durante las últimas semanas.",
      "paginas": ["P2", "P3", "P4", "P7"]
    },
    {
      "id": "H3",
      "texto": "La medida estará vigente durante 15 días.",
      "paginas": ["P3", "P4", "P7"]
    },
    {
      "id": "H4",
      "texto": "Incumplir la restricción puede costar una multa de hasta 800.000 pesos.",
      "paginas": ["P2", "P3", "P5", "P6", "P7"]
    },
    {
      "id": "H5",
      "texto": "La Alcaldía de Puerto Celeste decretó toque de queda entre las 10:00 p. m. y las 5:00 a. m.",
      "paginas": ["P3"]
    },
    {
      "id": "H6",
      "texto": "Un policía que pidió no ser citado aseguró que se planea extender la medida a todo el departamento.",
      "paginas": ["P1", "P2", "P4", "P5", "P7"]
    },
    {
      "id": "H7",
      "texto": "El toque de queda regirá por quince días.",
      "paginas": ["P2", "P3", "P4", "P7"]
    }
  ]
}
